#include <windows.h>
#include <stdio.h>
#include <stdlib.h>
#include "suballoc.h"
#define BASE 0x110000u
#define SIZE (1028u*1024u-64u*1024u)
static unsigned overcommit,overfree;
static NTSTATUS commit(ULONG a,ULONG n){if(a<BASE || a+n>BASE+SIZE)++overcommit;return 0;}
static NTSTATUS decommit(ULONG a,ULONG n){if(a<BASE || a+n>BASE+SIZE)++overfree;return 0;}
static void move(ULONG a,ULONG b,ULONG n){(void)a;(void)b;(void)n;}
int main(void){ULONG a;PVOID p=SAInitialize(BASE,SIZE,commit,decommit,move);
 if(!p || !SAAllocate(p,SIZE,&a) || a!=BASE || !SAFree(p,SIZE,a))return 2;
 printf("granularity=%u reserved=%u cross_commit=%u cross_decommit=%u\n",COMMIT_GRANULARITY,SIZE,overcommit,overfree);
 free(p);return (overcommit || overfree)?1:0;}
